    13\tmass outside the encoding image by evaluated reference inconsistency.\n    14\t\n    15\t## References\n    16\t\n    17\t- Blueprint `eq:qld-nonencoding-mass` and `lem:qld-nonencoding-mass-bound`.\n    18\t- `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:197-264,383-418`.\n    19\t- `docs/paper-gaps/qpbt_decoding-identity.tex`.\n    20\t- The reference and comparison constructions reused here are from commits\n    21\t  `55ae7487`, `36c07381`, `ff4c92d1`, `84c7ec43`, and `7f916eb8`.\n    22\t- These are auxiliary estimates for a supplied witness, not its construction.\n    23\t-/\n    24\t\n    25\topen scoped BigOperators Matrix MatrixOrder ComplexOrder\n    26\topen scoped Classical\n    27\t\n    28\tnamespace MIPStarRE.QPBT\n    29\t\n    30\topen MIPStarRE.LDT hiding Measurement\n    31\topen MIPStarRE.Quantum DistanceCalculus ProjectiveSetting\n    32\t\n    33\tnoncomputable section\n    34\t\n    35\t/-- For commuting families, reversing the order of the measurements preserves\n    36\tthe consistency defect. This is finite-sum algebra for opposite placements. -/\n    37\ttheorem consistencyDefect_comm_of_commute {X A I : Type*}\n    38\t    [Fintype X] [DecidableEq X] [Fintype A] [DecidableEq A]\n    39\t    [Fintype I] [DecidableEq I] (mu : Distribution X)\n    40\t    (first second : X → A → Op I) (psi : EuclideanSpace ℂ I)\n    41\t    (hcomm : ∀ x a b, first x a * second x b = second x b * first x a) :\n    42\t    consistencyDefect mu first second psi = consistencyDefect mu second first psi := by\n    43\t  unfold consistencyDefect\n    44\t  apply avgOver_congr\n    45\t  intro x\n    46\t  rw [Finset.sum_comm]\n    47\t  apply Finset.sum_congr rfl\n    48\t  intro b _\n    49\t  apply Finset.sum_congr rfl\n    50\t  intro a _\n    51\t  simp only [hcomm x a b, eq_comm]\n    52\t\n    53\t/-- A polynomial measurement's mass outside the encoding image is at most\n    54\tits evaluated inconsistency with an encoding-supported reference, plus `md/q`.\n    55\tThis is the Schwartz-Zippel step in blueprint `eq:qld-nonencoding-mass`.\n    56\tThe reference support is explicit because this auxiliary applies to any POVM;\n    57\tthe concrete reference above proves it without an additional strategy premise. -/\n    58\ttheorem mass_outside_encoding_le_evaluated_defect {P : AdmissibleParams}\n    59\t    {I J : Type*} [Fintype I] [DecidableEq I] [Fintype J] [DecidableEq J]\n    60\t    (meas : Measurement (Poly P) I) (reference : Measurement (Poly P) J)\n    61\t    (psi : EuclideanSpace ℂ (I × J)) (hpsi : ‖psi‖ = 1)\n    62\t    (hsupport : ∀ g, ¬ IsEncoding g → reference.effect g = 0) :\n    63\t    (∑ g ∈ Finset.univ.filter (fun g : Poly P => ¬ IsEncoding g),\n    64\t      stateQForm psi (heteroKron (meas.effect g) 1)) ≤\n    65\t      consistencyDefect (uniformDistribution (Fin P.m → PauliScalar P))\n    66\t        (fun u a => heteroKron ((meas.postprocess (fun g => evalPoly g u)).effect a) 1)\n    67\t        (fun u a => heteroKron 1 ((reference.postprocess\n    68\t          (fun g => evalPoly g u)).effect a)) psi + (P.m * P.d : ℝ) / P.q := by\n    69\t  classical\n    70\t  have hmass := mass_outside_support_le_point_defect meas reference psi\n    71\t    (Finset.univ.filter IsEncoding) (by simpa using hsupport)\n    72\t  simp only [Finset.mem_filter, Finset.mem_univ, true_and] at hmass\n    73\t  have hcollision := SandwichProduct.point_codeword_defect_le_avg_evaluated_add\n    74\t    meas reference psi evalPoly ((P.m * P.d : ℝ) / P.q) hpsi\n    75\t    (by positivity) poly_eval_collision_le\n    76\t  refine hmass.trans (hcollision.trans_eq ?_)\n    77\t  rw [SandwichProduct.consistencyDefect_placed_eq_avg_point]\n    78\t\n    79\tnamespace ProjectiveSetting\n    80\t\n    81\t/-- The ideal point measurement has zero off-diagonal mass on its EPR pair.\n    82\tThis follows from the existing unit diagonal-overlap calculation. -/\n    83\tprivate theorem tauPoint_offDiagonal_eq_zero {P : AdmissibleParams}\n    84\t    (W : PauliKind) (u : Fin P.m → PauliScalar P) :\n    85\t    (∑ a : PauliScalar P, ∑ b : PauliScalar P, if a = b then 0 else\n    86\t      stateQForm (eprState (PauliRegister P))\n    87\t        (heteroKron (tauPointProj W u a) (tauPointProj W u b))) = 0 := by\n    88\t  have h := point_defect_eq (leftPlacedMeasurement (tauPointMeas W u))\n    89\t    (rightPlacedMeasurement (tauPointMeas W u)) (eprState (PauliRegister P))\n    90\t  simpa only [leftPlacedMeasurement, rightPlacedMeasurement, Measurement.ofSumEqOne,\n    91\t    placed_product_stateQForm_eq, tauPointMeas, eprState_norm, one_pow,\n    92\t    sum_tauPointProj_pair_stateQForm_eprState, sub_self] using h\n    93\t\n    94\t/-- Adjoining the ideal point outcomes preserves the Pauli-basis check on the\n    95\ttwo-player expanded state, in the point--Pauli orientation. -/\n    96\ttheorem point_encodingPauli_consistency_eq {P : AdmissibleParams} {epsilon : ℝ}\n    97\t    (S : ProjectiveSetting P epsilon) (W : PauliKind) :\n    98\t    consistencyDefect (uniformDistribution (Fin P.m → PauliScalar P))\n    99\t        (fun u a => heteroKron ((S.pointMeasExp .alice W u).effect a) 1)\n   100\t        (fun u a => heteroKron 1 (((S.encodingPauliMeas .bob W).postprocess\n   101\t          (fun g => evalPoly g u)).effect a)) (ExtendedLineGame.pairState S) =\n   102\t      consistencyDefect (uniformDistribution (Fin P.m → PauliScalar P))\n   103\t        (fun u a => heteroKron ((S.pointMeas .alice W u).effect a) 1)\n   104\t        (fun u a => heteroKron 1 ((S.pauliEvalMeas .bob W u).effect a))\n   105\t        S.toStrategy.ψ := by\n   106\t  have h := consistencyDefect_convolution_eq_of_perfect\n   107\t    (uniformDistribution (Fin P.m → PauliScalar P))\n   108\t    (S.pointMeas .alice W) (S.pauliEvalMeas .bob W)\n   109\t    (tauPointMeas W) (tauPointMeas W) S.toStrategy.ψ\n   110\t    (eprState (PauliRegister P)) (eprState_norm _)\n   111\t    (tauPoint_offDiagonal_eq_zero W)\n   112\t  simpa only [pointMeasExp, Measurement.ofSumEqOne, expPointOp_eq_convolution,\n   113\t    encodingPauliMeas_eval_effect_eq_convolution, tauPointMeas,\n   114\t    ExtendedLineGame.pairState] using h\n   115\t\n   116\t/-- The same exact preservation holds in the Pauli--point orientation. -/\n   117\ttheorem encodingPauli_point_consistency_eq {P : AdmissibleParams} {epsilon : ℝ}\n   118\t    (S : ProjectiveSetting P epsilon) (W : PauliKind) :\n   119\t    consistencyDefect (uniformDistribution (Fin P.m → PauliScalar P))\n   120\t        (fun u a => heteroKron (((S.encodingPauliMeas .alice W).postprocess\n   121\t          (fun g => evalPoly g u)).effect a) 1)\n   122\t        (fun u a => heteroKron 1 ((S.pointMeasExp .bob W u).effect a))\n   123\t        (ExtendedLineGame.pairState S) =\n   124\t      consistencyDefect (uniformDistribution (Fin P.m → PauliScalar P))\n   125\t        (fun u a => heteroKron ((S.pauliEvalMeas .alice W u).effect a) 1)\n   126\t        (fun u a => heteroKron 1 ((S.pointMeas .bob W u).effect a))\n   127\t        S.toStrategy.ψ := by\n   128\t  have h := consistencyDefect_convolution_eq_of_perfect\n   129\t    (uniformDistribution (Fin P.m → PauliScalar P))\n   130\t    (S.pauliEvalMeas .alice W) (S.pointMeas .bob W)\n   131\t    (tauPointMeas W) (tauPointMeas W) S.toStrategy.ψ\n   132\t    (eprState (PauliRegister P)) (eprState_norm _)\n   133\t    (tauPoint_offDiagonal_eq_zero W)\n   134\t  simpa only [pointMeasExp, Measurement.ofSumEqOne, expPointOp_eq_convolution,\n   135\t    encodingPauliMeas_eval_effect_eq_convolution, tauPointMeas,\n   136\t    ExtendedLineGame.pairState] using h\n   137\t\n   138\t/-- Adjoining the same ideal point measurements also preserves point\n   139\tself-consistency exactly. -/\n   140\ttheorem expanded_point_consistency_eq {P : AdmissibleParams} {epsilon : ℝ}\n   141\t    (S : ProjectiveSetting P epsilon) (W : PauliKind) :\n   142\t    consistencyDefect (uniformDistribution (Fin P.m → PauliScalar P))\n   143\t        (fun u a => heteroKron ((S.pointMeasExp .alice W u).effect a) 1)\n   144\t        (fun u a => heteroKron 1 ((S.pointMeasExp .bob W u).effect a))\n   145\t        (ExtendedLineGame.pairState S) =\n   146\t      consistencyDefect (uniformDistribution (Fin P.m → PauliScalar P))\n   147\t        (fun u a => heteroKron ((S.pointMeas .alice W u).effect a) 1)\n   148\t        (fun u a => heteroKron 1 ((S.pointMeas .bob W u).effect a))\n   149\t        S.toStrategy.ψ := by\n   150\t  have h := consistencyDefect_convolution_eq_of_perfect\n   151\t    (uniformDistribution (Fin P.m → PauliScalar P))\n   152\t    (S.pointMeas .alice W) (S.pointMeas .bob W)\n   153\t    (tauPointMeas W) (tauPointMeas W) S.toStrategy.ψ\n   154\t    (eprState (PauliRegister P)) (eprState_norm _)\n   155\t    (tauPoint_offDiagonal_eq_zero W)\n   156\t  simpa only [pointMeasExp, Measurement.ofSumEqOne, expPointOp_eq_convolution,\n   157\t    tauPointMeas, ExtendedLineGame.pairState] using h\n   158\t\n   159\tend ProjectiveSetting\n   160\t\n   161\t/-- The right-hand marginal version of the support estimate, obtained by\n   162\tinterchanging the two tensor factors and using the same collision bound. -/\n   163\ttheorem right_mass_outside_encoding_le_evaluated_defect {P : AdmissibleParams}\n   164\t    {I J : Type*} [Fintype I] [DecidableEq I] [Fintype J] [DecidableEq J]\n   165\t    (reference : Measurement (Poly P) I) (meas : Measurement (Poly P) J)\n   166\t    (psi : EuclideanSpace ℂ (I × J)) (hpsi : ‖psi‖ = 1)\n   167\t    (hsupport : ∀ g, ¬ IsEncoding g → reference.effect g = 0) :\n   168\t    (∑ g ∈ Finset.univ.filter (fun g : Poly P => ¬ IsEncoding g),\n   169\t      stateQForm psi (heteroKron 1 (meas.effect g))) ≤\n   170\t      consistencyDefect (uniformDistribution (Fin P.m → PauliScalar P))\n   171\t        (fun u a => heteroKron ((reference.postprocess\n   172\t          (fun g => evalPoly g u)).effect a) 1)\n   173\t        (fun u a => heteroKron 1 ((meas.postprocess (fun g => evalPoly g u)).effect a))\n   174\t        psi + (P.m * P.d : ℝ) / P.q := by\n   175\t  have h := mass_outside_encoding_le_evaluated_defect meas reference\n   176\t    (reindexState (Equiv.prodComm I J) psi)\n   177\t    (by rw [reindexState_norm_eq, hpsi]) hsupport\n   178\t  simpa only [WinImplications.stateQForm_reindexState,\n   179\t    WinImplications.reindexOp_prodComm_heteroKron,\n   180\t    WinImplications.consistencyDefect_swappedState] using h\n   181\t\n   182\t/-- Both evaluated global marginals are consistent with the opposite\n   183\tencoding-supported reference. The universal square-root coefficient comes\n   184\tfrom the two Pauli-basis checks and point self-consistency; it does not assume\n   185\tthe non-encoding support estimate or the existence of a global witness. -/\n   186\ttheorem global_marginal_encoding_consistency :\n   187\t    ∃ C : ℝ, 1 ≤ C ∧ ∀ (P : AdmissibleParams) (epsilon deltaG : ℝ),\n   188\t      0 ≤ epsilon → ∀ (S : ProjectiveSetting P epsilon)\n   189\t        (w : GlobalPairWitness S deltaG) (W : PauliKind),\n   190\t      consistencyDefect (uniformDistribution (Fin P.m → PauliScalar P))\n   191\t          (fun u a => heteroKron (((w.marginalPoly .alice W).postprocess\n   192\t            (fun g => evalPoly g u)).effect a) 1)\n   193\t          (fun u a => heteroKron 1 (((S.encodingPauliMeas .bob W).postprocess\n   194\t            (fun g => evalPoly g u)).effect a)) (ExtendedLineGame.pairState S) ≤\n   195\t        deltaG + C * Real.sqrt epsilon ∧\n   196\t      consistencyDefect (uniformDistribution (Fin P.m → PauliScalar P))\n   197\t          (fun u a => heteroKron (((S.encodingPauliMeas .alice W).postprocess\n   198\t            (fun g => evalPoly g u)).effect a) 1)\n   199\t          (fun u a => heteroKron 1 (((w.marginalPoly .bob W).postprocess\n   200\t            (fun g => evalPoly g u)).effect a)) (ExtendedLineGame.pairState S) ≤\n   201\t        deltaG + C * Real.sqrt epsilon := by\n   202\t  obtain ⟨C1, hC1, hforward⟩ := win_pauli_basis_cons\n   203\t  obtain ⟨C2, hC2, hreverse⟩ := WinImplications.win_pauli_basis_cons_interchanged_proof\n   204\t  let E : ℝ := Fintype.card PauliEdge\n   205\t  let K : ℝ := max C1 C2\n   206\t  refine ⟨1 + 2 * Real.sqrt (E + K), by linarith [Real.sqrt_nonneg (E + K)], ?_⟩\n   207\t  intro P epsilon deltaG hepsilon S w W\n   208\t  let mu := uniformDistribution (Fin P.m → PauliScalar P)\n   209\t  let psi := ExtendedLineGame.pairState S\n   210\t  let pointA := fun u => leftPlacedMeasurement (ιB := S.ExpandedLocalSpace .bob)\n   211\t    (S.pointMeasExp .alice W u)\n   212\t  let pointB := fun u => rightPlacedMeasurement (ιA := S.ExpandedLocalSpace .alice)\n   213\t    (S.pointMeasExp .bob W u)\n   214\t  let refA := fun u => leftPlacedMeasurement (ιB := S.ExpandedLocalSpace .bob)\n   215\t    ((S.encodingPauliMeas .alice W).postprocess (fun g => evalPoly g u))\n   216\t  let refB := fun u => rightPlacedMeasurement (ιA := S.ExpandedLocalSpace .alice)\n   217\t    ((S.encodingPauliMeas .bob W).postprocess (fun g => evalPoly g u))\n   218\t  let margA := fun u => leftPlacedMeasurement (ιB := S.ExpandedLocalSpace .bob)\n   219\t    ((w.marginalPoly .alice W).postprocess (fun g => evalPoly g u))\n   220\t  let margB := fun u => rightPlacedMeasurement (ιA := S.ExpandedLocalSpace .alice)\n   221\t    ((w.marginalPoly .bob W).postprocess (fun g => evalPoly g u))\n   222\t  have hpost (side : PlayerSide) (u : Fin P.m → PauliScalar P) :\n   223\t      (w.marginalPoly side W).postprocess (fun g => evalPoly g u) =\n   224\t        (w.Smeas side).postprocess (evalAt W u) := by\n   225\t    rw [GlobalPairWitness.marginalPoly, Measurement.postprocess_comp]\n   226\t    cases W <;> rfl\n   227\t  have hab : consistencyDefect mu (fun u a => (margA u).effect a)\n   228\t      (fun u a => (pointB u).effect a) psi ≤ deltaG := by\n   229\t    change consistencyDefect mu\n   230\t      (fun u a => heteroKron (((w.marginalPoly .alice W).postprocess\n   231\t        (fun g => evalPoly g u)).effect a) 1)\n   232\t      (fun u a => heteroKron 1 ((S.pointMeasExp .bob W u).effect a)) psi ≤ deltaG\n   233\t    rw [S.consistencyDefect_pairState_eq_AA'_BA'']\n   234\t    simpa only [hpost] using w.point_consistent_alice W\n   235\t  have hba : consistencyDefect mu (fun u a => (margB u).effect a)\n   236\t      (fun u a => (pointA u).effect a) psi ≤ deltaG := by\n   237\t    rw [consistencyDefect_comm_of_commute _ _ _ _ (by\n   238\t      intro u a b\n   239\t      exact (WinImplications.heteroKron_left_right_comm _ _).symm)]\n   240\t    change consistencyDefect mu\n   241\t      (fun u a => heteroKron ((S.pointMeasExp .alice W u).effect a) 1)\n   242\t      (fun u a => heteroKron 1 (((w.marginalPoly .bob W).postprocess\n   243\t        (fun g => evalPoly g u)).effect a)) psi ≤ deltaG\n   244\t    rw [S.consistencyDefect_pairState_eq_AB''_BB',\n   245\t      consistencyDefect_comm_of_commute _ _ _ _ (by\n   246\t        intro u a b\n   247\t        exact S.place_comm .AB'' .BB' trivial _ _)]\n   248\t    simpa only [hpost] using w.point_consistent_bob W\n   249\t  have hpoints : consistencyDefect mu (fun u a => (pointA u).effect a)\n   250\t      (fun u a => (pointB u).effect a) psi ≤ E * epsilon := by\n   251\t    change consistencyDefect mu\n   252\t      (fun u a => heteroKron ((S.pointMeasExp .alice W u).effect a) 1)\n   253\t      (fun u a => heteroKron 1 ((S.pointMeasExp .bob W u).effect a)) psi ≤ _\n   254\t    rw [S.expanded_point_consistency_eq]\n   255\t    exact point_self_consistency_le S W\n   256\t  have hpoints' : consistencyDefect mu (fun u a => (pointB u).effect a)\n   257\t      (fun u a => (pointA u).effect a) psi ≤ E * epsilon := by\n   258\t    rw [consistencyDefect_comm_of_commute _ _ _ _ (by\n   259\t      intro u a b\n   260\t      exact (WinImplications.heteroKron_left_right_comm _ _).symm)]\n   261\t    exact hpoints\n   262\t  have hpb : consistencyDefect mu (fun u a => (pointA u).effect a)\n   263\t      (fun u a => (refB u).effect a) psi ≤ K * epsilon := by\n   264\t    change consistencyDefect mu\n   265\t      (fun u a => heteroKron ((S.pointMeasExp .alice W u).effect a) 1)\n   266\t      (fun u a => heteroKron 1 (((S.encodingPauliMeas .bob W).postprocess\n   267\t        (fun g => evalPoly g u)).effect a)) psi ≤ _\n   268\t    rw [S.point_encodingPauli_consistency_eq]\n   269\t    exact (hforward P epsilon S hepsilon W).trans\n   270\t      (mul_le_mul_of_nonneg_right (le_max_left _ _) hepsilon)\n   271\t  have hpa : consistencyDefect mu (fun u a => (pointB u).effect a)\n   272\t      (fun u a => (refA u).effect a) psi ≤ K * epsilon := by\n   273\t    rw [consistencyDefect_comm_of_commute _ _ _ _ (by\n   274\t      intro u a b\n   275\t      exact (WinImplications.heteroKron_left_right_comm _ _).symm)]\n   276\t    change consistencyDefect mu\n   277\t      (fun u a => heteroKron (((S.encodingPauliMeas .alice W).postprocess\n   278\t        (fun g => evalPoly g u)).effect a) 1)\n   279\t      (fun u a => heteroKron 1 ((S.pointMeasExp .bob W u).effect a)) psi ≤ _\n   280\t    rw [S.encodingPauli_point_consistency_eq]\n   281\t    exact (hreverse P epsilon S hepsilon W).trans\n   282\t      (mul_le_mul_of_nonneg_right (le_max_right _ _) hepsilon)\n   283\t  have hscalar : deltaG + 2 * Real.sqrt (E * epsilon + K * epsilon) ≤\n   284\t      deltaG + (1 + 2 * Real.sqrt (E + K)) * Real.sqrt epsilon := by\n   285\t    have hEK : 0 ≤ E + K := add_nonneg (Nat.cast_nonneg _)\n   286\t      (le_trans (by linarith : 0 ≤ C1) (le_max_left _ _))\n   287\t    rw [← add_mul, Real.sqrt_mul hEK]\n   288\t    nlinarith [Real.sqrt_nonneg epsilon]\n   289\t  constructor\n   290\t  · exact (consistencyDefect_trans_le mu margA pointB pointA refB psi\n   291\t      deltaG (E * epsilon) (K * epsilon) (uniformDistribution_isProbability _)\n   292\t      (ExtendedLineGame.pairState_norm S) hab hpoints hpb).trans hscalar\n   293\t  · have h := (consistencyDefect_trans_le mu margB pointA pointB refA psi\n   294\t      deltaG (E * epsilon) (K * epsilon) (uniformDistribution_isProbability _)\n   295\t      (ExtendedLineGame.pairState_norm S) hba hpoints' hpa).trans hscalar\n   296\t    rw [consistencyDefect_comm_of_commute _ _ _ _ (by\n   297\t      intro u a b\n   298\t      exact (WinImplications.heteroKron_left_right_comm _ _).symm)] at h\n   299\t    exact h\n   300\t\n   301\t/-- A marginal acting on `AA'` has the same mass in the extraction-block\n   302\tnotation and the two-player expanded state. The unused registers carry identities. -/\n   303\ttheorem stateQForm_placeSide_alice_tensor_one {P : AdmissibleParams} {epsilon : ℝ}\n   304\t    (S : ProjectiveSetting P epsilon) (A : Op (S.ExpandedLocalSpace .alice))\n   305\t    (hA : A.IsHermitian) :\n   306\t    stateQForm S.psiHat (S.placeSide .alice (heteroKron A (1 : Op (PauliRegister P)))) =\n   307\t      stateQForm (ExtendedLineGame.pairState S) (heteroKron A 1) := by\n   308\t  have hplace : S.placeSide .alice (heteroKron A (1 : Op (PauliRegister P))) =\n   309\t      S.place .AA' A := by\n   310\t    ext row col\n   311\t    simp only [placeSide, sixRegExtractionEquiv, reindexOp, place, heteroKron,\n   312\t      Matrix.kronecker, Matrix.one_apply, mul_ite, ite_mul]\n   313\t    split_ifs <;> simp_all\n   314\t    rfl\n   315\t  rw [hplace]\n   316\t  have h := ExtendedLineGame.stateQForm_pairState_eq_AA'_BA'' S A 1 hA\n   317\t    Matrix.isHermitian_one\n   318\t  have hone : S.place .BA'' (1 : Op (S.ExpandedLocalSpace .bob)) = 1 := by\n   319\t    convert S.place_one .BA'' using 1\n   320\t    rfl\n   321\t  rw [hone, Matrix.mul_one] at h\n   322\t  exact h.symm\n   323\t\n   324\t/-- The corresponding marginal-mass identity for `BB'`. The opposite placement\n   325\tuses the second EPR pair, as in the witness's Bob consistency hypothesis. -/\n   326\ttheorem stateQForm_placeSide_bob_tensor_one {P : AdmissibleParams} {epsilon : ℝ}\n   327\t    (S : ProjectiveSetting P epsilon) (B : Op (S.ExpandedLocalSpace .bob))\n   328\t    (hB : B.IsHermitian) :\n   329\t    stateQForm S.psiHat (S.placeSide .bob (heteroKron B (1 : Op (PauliRegister P)))) =\n   330\t      stateQForm (ExtendedLineGame.pairState S) (heteroKron 1 B) := by\n   331\t  have hplace : S.placeSide .bob (heteroKron B (1 : Op (PauliRegister P))) =\n   332\t      S.place .BB' B := by\n   333\t    ext row col\n   334\t    simp only [placeSide, sixRegExtractionEquiv, reindexOp, place, heteroKron,\n   335\t      Matrix.kronecker, Matrix.one_apply, mul_ite, ite_mul]\n   336\t    split_ifs <;> simp_all\n   337\t    rfl\n   338\t  rw [hplace]\n   339\t  have h := ExtendedLineGame.stateQForm_pairState_eq_AB''_BB' S 1 B\n   340\t    Matrix.isHermitian_one hB\n   341\t  have hone : S.place .AB'' (1 : Op (S.ExpandedLocalSpace .alice)) = 1 := by\n   342\t    convert S.place_one .AB'' using 1\n   343\t    rfl\n   344\t  rw [hone, Matrix.one_mul] at h\n   345\t  exact h.symm\n   346\t\n   347\tend\n   348\t\n   349\tend MIPStarRE.QPBT\n     1\timport MIPStarRE.QPBT.Extraction.Observables\n     2\timport MIPStarRE.QPBT.Combining.Points.PlacementSupport\n     3\timport MIPStarRE.QPBT.Combining.Lines.ConsistencyPositivity\n     4\t\n     5\t/-!\n     6\t# Point consistency after decoding polynomial outcomes\n     7\t\n     8\tThis module expands the overlap of an original point measurement with a\n     9\tpulled-apart measurement. The decoded polynomial is kept explicit, so the\n    10\tcalculation does not use the decoder identity outside the encoding image.\n    11\t\n    12\t## References\n    13\t\n    14\tThese are auxiliary identities for blueprint `lem:qld-construct-the-paulis`,\n    15\tpaper `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1483-1492`.\n    16\tThe restriction on the decoder identity is recorded in\n    17\t`docs/paper-gaps/qpbt_decoding-identity.tex`.\n    18\t-/\n    19\t\n    20\topen scoped BigOperators Matrix MatrixOrder ComplexOrder\n    21\t\n    22\tnamespace MIPStarRE.QPBT\n    23\t\n    24\topen MIPStarRE.LDT hiding Measurement\n    25\topen MIPStarRE.Quantum DistanceCalculus\n    26\t\n    27\tnoncomputable section\n    28\t\n    29\tnamespace ProjectiveSetting\n    30\t\n    31\tvariable {P : AdmissibleParams} {epsilon : ℝ}\n    32\t\n    33\t/-- Placing a tensor with an identity on Bob's last register recovers `BB'`. -/\n    34\ttheorem placeSide_bob_tensor_one (S : ProjectiveSetting P epsilon)\n    35\t    (B : Op (S.ExpandedLocalSpace .bob)) :\n    36\t    S.placeSide .bob (heteroKron B (1 : Op (PauliRegister P))) = S.place .BB' B := by\n    37\t  ext row col\n    38\t  simp [placeSide, sixRegExtractionEquiv, reindexOp, heteroKron, Matrix.kronecker,\n    39\t    place, Matrix.one_apply, Prod.ext_iff, ite_and, mul_ite, ite_mul]\n    40\t  split_ifs <;> rfl\n    41\t\n    42\t/-- The point factor on `A` and the factors on `BB'B''` can be regrouped as\n    43\tthe factors on `BB'` and `AB''`, without moving any register. -/\n    44\ttheorem placePlayer_alice_mul_placeSide_bob_tensor (S : ProjectiveSetting P epsilon)\n    45\t    (A : Op S.toStrategy.ιA) (B : Op (S.ExpandedLocalSpace .bob))\n    46\t    (T : Op (PauliRegister P)) :\n    47\t    S.placePlayer .alice A * S.placeSide .bob (heteroKron B T) =\n    48\t      S.place .BB' B * S.place .AB'' (heteroKron A T) := by\n    49\t  classical\n    50\t  ext row col\n    51\t  simp [placePlayer, placeSide, sixRegExtractionEquiv, reindexOp, heteroKron,\n    52\t    Matrix.kronecker, place, Matrix.mul_apply, Fintype.sum_prod_type,\n    53\t    Matrix.one_apply, Prod.ext_iff, ite_and, mul_ite, ite_mul, mul_left_comm]\n    54\t  rfl\n    55\t\n    56\t/-- Bob's extraction-block placement preserves finite sums. -/\n    57\ttheorem placeSide_bob_finset_sum (S : ProjectiveSetting P epsilon)\n    58\t    {I : Type*} (s : Finset I) (B : I → Op (ExtractionBlock P S.toStrategy.ιB)) :\n    59\t    S.placeSide .bob (∑ i ∈ s, B i) = ∑ i ∈ s, S.placeSide .bob (B i