e ((S.pointMeas .alice W u).effect a) *\n    97\t      S.placeSide .bob (tildeM w .bob W (indicatorVec u) a)) =\n    98\t      ∑ g : Poly P, S.place .BB' ((w.marginalPoly .bob W).effect g) *\n    99\t        S.place .AB'' ((S.pointMeasExp .alice W u).effect\n   100\t          (dotProduct (decodeFq g) (indicatorVec u))) := by\n   101\t  classical\n   102\t  simp only [tildeM, S.placeSide_bob_finset_sum, Finset.mul_sum]\n   103\t  rw [Finset.sum_comm]\n   104\t  apply Finset.sum_congr rfl\n   105\t  intro g _\n   106\t  simp only [S.placePlayer_alice_mul_placeSide_bob_tensor]\n   107\t  rw [← Finset.mul_sum, ← S.place_finset_sum,\n   108\t    S.pointMeasExp_effect_eq_sum_sub .alice W u]\n   109\t  rfl\n   110\t\n   111\t/-- The pulled-apart consistency defect is one minus the decoded overlap.\n   112\tThis packages completeness with the first three lines of the source's\n   113\tcalculation, still without imposing an encoding restriction. -/\n   114\ttheorem tildeM_consistencyDefect_eq_one_sub_decoded_overlap\n   115\t    {P : AdmissibleParams} {epsilon deltaG : ℝ} {S : ProjectiveSetting P epsilon}\n   116\t    (w : GlobalPairWitness S deltaG) (W : PauliKind) :\n   117\t    consistencyDefect (uniformDistribution (Fin P.m → PauliScalar P))\n   118\t      (fun u a => S.placePlayer .alice ((S.pointMeas .alice W u).effect a))\n   119\t      (fun u a => S.placeSide .bob (tildeM w .bob W (indicatorVec u) a)) S.psiHat =\n   120\t      1 - avgOver (uniformDistribution (Fin P.m → PauliScalar P)) (fun u =>\n   121\t        ∑ g : Poly P, stateQForm S.psiHat\n   122\t          (S.place .BB' ((w.marginalPoly .bob W).effect g) *\n   123\t            S.place .AB'' ((S.pointMeasExp .alice W u).effect\n   124\t              (dotProduct (decodeFq g) (indicatorVec u))))) := by\n   125\t  classical\n   126\t  let point := fun u : Fin P.m → PauliScalar P =>\n   127\t    S.placedMeasurement .AA' (leftPlacedMeasurement (S.pointMeas .alice W u))\n   128\t  let pulled : (Fin P.m → PauliScalar