ibleParams} {epsilon deltaG : ℝ} {S : ProjectiveSetting P epsilon}\n   164\t    (w : GlobalPairWitness S deltaG) (W : PauliKind)\n   165\t    (u : Fin P.m → PauliScalar P) :\n   166\t    (∑ g : Poly P, stateQForm S.psiHat\n   167\t      (S.place .BB' ((w.marginalPoly .bob W).effect g) *\n   168\t        S.place .AB'' ((S.pointMeasExp .alice W u).effect (MvPolynomial.eval u g.1)))) ≤\n   169\t      (∑ g : Poly P, stateQForm S.psiHat\n   170\t        (S.place .BB' ((w.marginalPoly .bob W).effect g) *\n   171\t          S.place .AB'' ((S.pointMeasExp .alice W u).effect\n   172\t            (dotProduct (decodeFq g) (indicatorVec u))))) +\n   173\t      ∑ g ∈ Finset.univ.filter (fun g : Poly P => ¬ IsEncoding g),\n   174\t        stateQForm S.psiHat (S.place .BB' ((w.marginalPoly .bob W).effect g)) := by\n   175\t  classical\n   176\t  have hpos (g : Poly P) (a : PauliScalar P) :\n   177\t      0 ≤ stateQForm S.psiHat\n   178\t        (S.place .BB' ((w.marginalPoly .bob W).effect g) *\n   179\t          S.place .AB'' ((S.pointMeasExp .alice W u).effect a)) :=\n   180\t    stateQForm_nonneg _ (S.place_mul_place_nonneg .BB' .AB'' (by trivial)\n   181\t      ((w.marginalPoly .bob W).pos g) ((S.pointMeasExp .alice W u).pos a))\n   182\t  have hsum (g : Poly P) :\n   183\t      (∑ a : PauliScalar P, stateQForm S.psiHat\n   184\t        (S.place .BB' ((w.marginalPoly .bob W).effect g) *\n   185\t          S.place .AB'' ((S.pointMeasExp .alice W u).effect a))) =\n   186\t        stateQForm S.psiHat (S.place .BB' ((w.marginalPoly .bob W).effect g)) := by\n   187\t    have hc : (∑ a : PauliScalar P,\n   188\t        S.place .AB'' ((S.pointMeasExp .alice W u).effect a)) = 1 :=\n   189\t      (S.placedMeasurement .AB'' (S.pointMeasExp .alice W u)).sum_eq_one\n   190\t    rw [← stateQForm_finset_sum, ← Finset.mul_sum, hc, mul_one]\n   191\t  rw [Finset.sum_filter, ← Finset.sum_add_distrib]\n   192\t  apply Finset.sum_le_sum\n   193\t  intro g _\n   194\t  by_cases hg : IsEncoding g\