igOperators Matrix MatrixOrder ComplexOrder\n    23\t\n    24\tnamespace MIPStarRE.QPBT\n    25\t\n    26\topen MIPStarRE.LDT hiding Measurement\n    27\topen MIPStarRE.Quantum DistanceCalculus\n    28\t\n    29\tsection Factorization\n    30\t\n    31\tvariable {ιA ιB κA κB : Type*}\n    32\t  [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB]\n    33\t  [Fintype κA] [DecidableEq κA] [Fintype κB] [DecidableEq κB]\n    34\t\n    35\t/-- Joint expectations factor after regrouping an independent pair of bipartite\n    36\tstates by player. The shuffle sends `((i, j), (k, l))` to `((i, k), (j, l))`. -/\n    37\ttheorem inner_prodShuffle_vecTensor_heteroKron\n    38\t    (ψ : EuclideanSpace ℂ (ιA × ιB)) (φ : EuclideanSpace ℂ (κA × κB))\n    39\t    (A : Op ιA) (B : Op ιB) (R : Op κA) (T : Op κB) :\n    40\t    inner ℂ (reindexState prodShuffle (vecTensor ψ φ))\n    41\t        (applyOperatorToState (heteroKron (heteroKron A R) (heteroKron B T))\n    42\t          (reindexState prodShuffle (vecTensor ψ φ))) =\n    43\t      inner ℂ ψ (applyOperatorToState (heteroKron A B) ψ) *\n    44\t        inner ℂ φ (applyOperatorToState (heteroKron R T) φ) := by\n    45\t  simp only [applyOperatorToState, Matrix.toEuclideanLin, Matrix.toLpLin_apply,\n    46\t    EuclideanSpace.inner_eq_star_dotProduct, dotProduct, Matrix.mulVec]\n    47\t  simp_rw [Finset.sum_mul, Finset.mul_sum]\n    48\t  rw [← (prodShuffle : (ιA × ιB) × (κA × κB) ≃ _).sum_comp]\n    49\t  simp_rw [← (prodShuffle : (ιA × ιB) × (κA × κB) ≃ _).sum_comp]\n    50\t  change (∑ p : (ιA × ιB) × (κA × κB), ∑ q : (ιA × ιB) × (κA × κB),\n    51\t    ((A p.1.1 q.1.1 * R p.2.1 q.2.1) * (B p.1.2 q.1.2 * T p.2.2 q.2.2) *\n    52\t      (ψ q.1 * φ q.2)) * star (ψ p.1 * φ p.2)) =\n    53\t    ∑ i : ιA × ιB, ∑ j : ιA × ιB, ∑ k : κA × κB, ∑ l : κA × κB,\n    54\t      ((A i.1 j.1 * B i.2 j.2 * ψ j) * star (ψ i)) *\n    55\t        ((R k.1 l.1 * T k.2 l.2 * φ l) * star (φ k))\n    56\t  simp only [Fintype.sum_prod_type (α₁ := ιA × ιB) (α₂ := κA × κB), star_mul]\n    57\t  conv_lhs =>\n    58\t    arg 2\n    59\t    ext i\n    60\t    rw [Finset.sum_comm]\n    61\t  congr! 4 with i j k l\n    62\t  ring\n    63\t\n    64\t/-- For positive ancillary effects, the real joint expectation factors on the\n    65\tshuffled tensor state. No normalization or positivity of `A` and `B` is needed. -/\n    66\ttheorem stateQForm_prodShuffle_vecTensor_heteroKron\n    67\t    (ψ : EuclideanSpace ℂ (ιA × ιB)) (φ : EuclideanSpace ℂ (κA × κB))\n    68\t    (A : Op ιA) (B : Op ιB) {R : Op κA} {T : Op κB}\n    69\t    (hR : 0 ≤ R) (hT : 0 ≤ T) :\n    70\t    stateQForm (reindexState prodShuffle (vecTensor ψ φ))\n    71\t        (heteroKron (heteroKron A R) (heteroKron B T)) =\n    72\t      stateQForm ψ (heteroKron A B) * stateQForm φ (heteroKron R T) := by\n    73\t  have hnonneg := (Matrix.nonneg_iff_posSemidef.mp\n    74\t    (kronecker_nonneg hR hT)).dotProduct_mulVec_nonneg φ.ofLp\n    75\t  have him : (inner ℂ φ (applyOperatorToState (heteroKron R T) φ)).im = 0 := by\n    76\t    simpa only [applyOperatorToState, Matrix.toEuclideanLin, Matrix.toLpLin_apply,\n    77\t      EuclideanSpace.inner_eq_star_dotProduct, dotProduct_comm, heteroKron] using\n    78\t      (Complex.nonneg_iff.mp hnonneg).2.symm\n    79\t  simp only [stateQForm, inner_prodShuffle_vecTensor_heteroKron, Complex.mul_re,\n    80\t    him, mul_zero, sub_zero]\n    81\t\n    82\tend Factorization\n    83\t\n    84\t/-- An additive convolution of effect families can be indexed by the ancillary\n    85\tanswer alone. This is the finite-fiber form of the expanded point construction. -/\n    86\ttheorem sum_add_fiber_heteroKron {G ι κ : Type*}\n    87\t    [Fintype G] [DecidableEq G] [AddCommGroup G]\n    88\t    (A : G → Op ι) (R : G → Op κ) (z : G) :\n    89\t    (∑ p ∈ Finset.univ.filter (fun p : G × G => p.1 + p.2 = z),\n    90\t      heteroKron (A p.1) (R p.2)) =\n    91\t      ∑ c : G, heteroKron (A (z - c)) (R c) := by\n    92\t  rw [Finset.sum_filter, Fintype.sum_prod_type, Finset.sum_comm]\n    93\t  simp only [← eq_sub_iff_add_eq, Finset.sum_ite_eq', Finset.mem_univ, if_true]\n    94\t\n    95\t/-- Averaging a common additive shift preserves the off-diagonal mass of any\n    96\tweight function. The ancillary joint weights are supported on the diagonal\n    97\tand have total diagonal mass one. -/\n    98\tprivate theorem sum_convolution_off_diagonal_eq {G : Type*}\n    99\t    [Fintype G] [DecidableEq G] [AddCommGroup G]\n   100\t    (p q : G → G → ℝ) (hzero : ∀ c d, c ≠ d → q c d = 0)\n   101\t    (hdiag : ∑ c : G, q c c = 1) :\n   102\t    (∑ z : G, ∑ w : G, if z = w then 0 else\n   103\t      ∑ c : G, ∑ d : G, p (z - c) (w - d) * q c d) =\n   104\t      ∑ a : G, ∑ b : G, if a = b then 0 else p a b := by\n   105\t  have hinner (z w c : G) :\n   106\t      (∑ d : G, p (z - c) (w - d) * q c d) =\n   107\t        p (z - c) (w - c) * q c c := by\n   108\t    apply Finset.sum_eq_single c\n   109\t    · intro d _ hdc\n   110\t      rw [hzero c d hdc.symm, mul_zero]\n   111\t    · simp\n   112\t  have hshift (c : G) :\n   113\t      (∑ z : G, ∑ w : G, if z = w then 0 else p (z - c) (w - c)) =\n   114\t        ∑ a : G, ∑ b : G, if a = b then 0 else p a b := by\n   115\t    refine Fintype.sum_equiv (Equiv.subRight c) _ _ fun z => ?_\n   116\t    refine Fintype.sum_equiv (Equiv.subRight c) _ _ fun w => ?_\n   117\t    change (if z = w then 0 else p (z - c) (w - c)) =\n   118\t      if z - c = w - c then 0 else p (z - c) (w - c)\n   119\t    simp only [sub_left_inj]\n   120\t  simp_rw [hinner]\n   121\t  calc\n   122\t    (∑ z : G, ∑ w : G, if z = w then 0 else\n   123\t        ∑ c : G, p (z - c) (w - c) * q c c) =\n   124\t        ∑ z : G, ∑ w : G, ∑ c : G,\n   125\t          (if z = w then 0 else p (z - c) (w - c)) * q c c := by\n   126\t      apply Finset.sum_congr rfl\n   127\t      intro z _\n   128\t      apply Finset.sum_congr rfl\n   129\t      intro w _\n   130\t      by_cases hzw : z = w <;> simp [hzw]\n   131\t    _ = ∑ c : G, (∑ z : G, ∑ w : G,\n   132\t        if z = w then 0 else p (z - c) (w - c)) * q c c := by\n   133\t      simp_rw [Finset.sum_mul]\n   134\t      conv_lhs =>\n   135\t        arg 2\n   136\t        ext z\n   137\t        rw [Finset.sum_comm]\n   138\t      rw [Finset.sum_comm]\n   139\t    _ = _ := by\n   140\t      simp_rw [hshift]\n   141\t      rw [← Finset.mul_sum, hdiag, mul_one]\n   142\t\n   143\t/-- Independent additive convolution with a normalized, perfectly correlated\n   144\tancillary POVM pair preserves the consistency defect exactly. All four register\n   145\ttypes may differ, and neither the original state nor the question distribution\n   146\tneeds to be normalized. No measurement is assumed projective.\n   147\t\n   148\tThis is a generic auxiliary for the expanded point construction in paper\n   149\t`14_analysis_of_the_pauli_basis_test.tex:367-438` and\n   150\t`lem:qld-construct-the-paulis`, not the latter paper theorem. Its ancillary\n   151\tperfection hypothesis must be established for the concrete ideal measurements\n   152\tbefore specialization; that application is tracked in issue #267. -/\n   153\ttheorem consistencyDefect_convolution_eq_of_perfect\n   154\t    {X G ιA ιB κA κB : Type*}\n   155\t    [Fintype X] [DecidableEq X] [Fintype G] [DecidableEq G] [AddCommGroup G]\n   156\t    [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB]\n   157\t    [Fintype κA] [DecidableEq κA] [Fintype κB] [DecidableEq κB]\n   158\t    (μ : Distribution X) (A : X → Measurement G ιA) (B : X → Measurement G ιB)\n   159\t    (R : X → Measurement G κA) (T : X → Measurement G κB)\n   160\t    (ψ : EuclideanSpace ℂ (ιA × ιB)) (φ : EuclideanSpace ℂ (κA × κB))\n   161\t    (hφ : ‖φ‖ = 1)\n   162\t    (hperfect : ∀ x, (∑ c : G, ∑ d : G, if c = d then 0 else\n   163\t      stateQForm φ (heteroKron ((R x).effect c) ((T x).effect d))) = 0) :\n   164\t    consistencyDefect μ\n   165\t        (fun x z => heteroKron\n   166\t          (∑ p ∈ Finset.univ.filter (fun p : G × G => p.1 + p.2 = z),\n   167\t            heteroKron ((A x).effect p.1) ((R x).effect p.2)) 1)\n   168\t        (fun x z => heteroKron 1\n   169\t          (∑ p ∈ Finset.univ.filter (fun p : G × G => p.1 + p.2 = z),\n   170\t            heteroKron ((B x).effect p.1) ((T x).effect p.2)))\n   171\t        (reindexState prodShuffle (vecTensor ψ φ)) =\n   172\t      consistencyDefect μ (fun x a => heteroKron ((A x).effect a) 1)\n   173\t        (fun x b => heteroKron 1 ((B x).effect b)) ψ := by\n   174\t  unfold consistencyDefect\n   175\t  simp_rw [consistency_term_eq_stateQForm, placed_product_stateQForm_eq]\n   176\t  apply avgOver_congr\n   177\t  intro x\n   178\t  let q : G → G → ℝ := fun c d =>\n   179\t    stateQForm φ (heteroKron ((R x).effect c) ((T x).effect d))\n   180\t  have hnonneg (c d : G) : 0 ≤ q c d :=\n   181\t    stateQForm_nonneg φ (kronecker_nonneg ((R x).pos c) ((T x).pos d))\n   182\t  have hoff (c d : G) : 0 ≤ (if c = d then 0 else q c d) := by\n   183\t    split_ifs\n   184\t    · exact le_rfl\n   185\t    · exact hnonneg c d\n   186\t  have hzero (c d : G) (hcd : c ≠ d) : q c d = 0 := by\n   187\t    have hrow := (Finset.sum_eq_zero_iff_of_nonneg\n   188\t      (fun c _ => Finset.sum_nonneg (fun d _ => hoff c d))).mp (hperfect x)\n   189\t    have hterm := (Finset.sum_eq_zero_iff_of_nonneg\n   190\t      (fun d _ => hoff c d)).mp (hrow c (Finset.mem_univ c)) d (Finset.mem_univ d)\n   191\t    simpa only [if_neg hcd] using hterm\n   192\t  have hdiag : ∑ c : G, q c c = 1 := by\n   193\t    have h := point_defect_eq (leftPlacedMeasurement (R x))\n   194\t      (rightPlacedMeasurement (T x)) φ\n   195\t    simp only [leftPlacedMeasurement, rightPlacedMeasurement, Measurement.ofSumEqOne,\n   196\t      placed_product_stateQForm_eq, hperfect x, hφ, one_pow] at h\n   197\t    dsimp only [q]\n   198\t    linarith\n   199\t  have hfactor (a b c d : G) := stateQForm_prodShuffle_vecTensor_heteroKron ψ φ\n   200\t    ((A x).effect a) ((B x).effect b) ((R x).pos c) ((T x).pos d)\n   201\t  simp_rw [sum_add_fiber_heteroKron, heteroKron_finset_sum_left,\n   202\t    heteroKron_finset_sum_right, stateQForm_finset_sum, hfactor]\n   203\t  exact sum_convolution_off_diagonal_eq\n   204\t    (fun a b => stateQForm ψ (heteroKron ((A x).effect a) ((B x).effect b)))\n   205\t    q hzero hdiag\n   206\t\n   207\tend MIPStarRE.QPBT\n     1\timport MIPStarRE.QPBT.Games.Sandwich.Support\n     2\t\n     3\t/-! # Marginal mass outside the support of a reference measurement\n     4\t\n     5\tA complete reference measurement supported on an allowed outcome set bounds\n     6\tthe other measurement's mass outside that set by their bipartite consistency\n     7\tdefect. The measurements act on separate tensor factors of the same state.\n     8\tNeither projectivity nor state normalization is needed; for a unit vector the\n     9\tquadratic forms are the corresponding Born probabilities.\n    10\t\n    11\tThese are formalization-only auxiliary estimates for the non-encoding mass\n    12\tcalculation in blueprint `eq:qld-nonencoding-mass`. They can be composed with\n    13\t`SandwichProduct.point_codeword_defect_le_avg_evaluated_add` after constructing\n    14\tan encoding-supported reference measurement on the opposite tensor factor.\n    15\tThey do not construct that reference or establish its evaluated consistency,\n    16\tand do not prove `nonencodingMarginalMass_le` or global-pair witness existence.\n    17\t\n    18\t## References\n    19\t\n    20\t- Blueprint `eq:qld-nonencoding-mass` and `lem:qld-nonencoding-mass-bound`.\n    21\t- `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1483-1498`,\n    22\t  the consistency calculation in `lem:qld-construct-the-paulis` that the\n    23\t  blueprint's non-encoding mass estimate supports.\n    24\t- `references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:232-248`,\n    25\t  the bipartite consistency defect.\n    26\t-/\n    27\t\n    28\topen scoped BigOperators MatrixOrder\n    29\t\n    30\tnamespace MIPStarRE.QPBT\n    31\t\n    32\topen MIPStarRE.LDT hiding Measurement\n    33\topen MIPStarRE.Quantum DistanceCalculus\n    34\t\n    35\t/-- The mass of a measurement outside the support of a complete reference\n    36\tmeasurement is at most their off-diagonal tensor overlap. Completeness of the\n    37\treference expands each marginal mass into a row of joint probabilities;\n    38\tsupport makes the diagonal term zero, and positivity bounds the restricted\n    39\tsum by the full defect. This is a formalization-only auxiliary for blueprint\n    40\t`eq:qld-nonencoding-mass`, valid for arbitrary state vectors. -/\n    41\ttheorem mass_outside_support_le_point_defect\n    42\t    {Outcome Left Right : Type*}\n    43\t    [Fintype Outcome] [DecidableEq Outcome]\n    44\t    [Fintype Left] [DecidableEq Left] [Fintype Right] [DecidableEq Right]\n    45\t    (meas : Measurement Outcome Left) (reference : Measurement Outcome Right)\n    46\t    (psi : EuclideanSpace ℂ (Left × Right)) (allowed : Finset Outcome)\n    47\t    (hsupport : ∀ outcome, outcome ∉ allowed → reference.effect outcome = 0) :\n    48\t    (∑ outcome ∈ Finset.univ.filter (fun outcome => outcome ∉ allowed),\n    49\t      stateQForm psi (heteroKron (meas.effect outcome) 1)) ≤\n    50\t      ∑ outcome : Outcome, ∑ other : Outcome, if outcome = other then 0 else\n    51\t        stateQForm psi (heteroKron (meas.effect outcome) (reference.effect other)) := by\n    52\t  have hnonneg (outcome other : Outcome) :\n    53\t      0 ≤ stateQForm psi (heteroKron (meas.effect outcome) (reference.effect other)) :=\n    54\t    stateQForm_nonneg psi (kronecker_nonneg (meas.pos outcome) (reference.pos other))\n    55\t  calc\n    56\t    (∑ outcome ∈ Finset.univ.filter (fun outcome => outcome ∉ allowed),\n    57\t        stateQForm psi (heteroKron (meas.effect outcome) 1)) =\n    58\t        ∑ outcome ∈ Finset.univ.filter (fun outcome => outcome ∉ allowed),\n    59\t          ∑ other : Outcome, if outcome = other then 0 else\n    60\t            stateQForm psi\n    61\t              (heteroKron (meas.effect outcome) (reference.effect other)) := by\n    62\t      apply Finset.sum_congr rfl\n    63\t      intro outcome houtcome\n    64\t      have hzero := hsupport outcome (Finset.mem_filter.mp houtcome).2\n    65\t      rw [← reference.sum_eq_one, heteroKron_finset_sum_right, stateQForm_finset_sum]\n    66\t      apply Finset.sum_congr rfl\n    67\t      intro other _\n    68\t      by_cases heq : outcome = other\n    69\t      · subst other\n    70\t        simp [hzero, heteroKron, stateQForm, applyOperatorToState]\n    71\t      · rw [if_neg heq]\n    72\t    _ ≤ _ := by\n    73\t      apply Finset.sum_le_sum_of_subset_of_nonneg (Finset.filter_subset _ _)\n    74\t      intro outcome _ _\n    75\t      apply Finset.sum_nonneg\n    76\t      intro other _\n    77\t      split_ifs\n    78\t      · exact le_rfl\n    79\t      · exact hnonneg outcome other\n    80\t\n    81\t/-- Averaging the supported-reference mass bound gives the same inequality\n    82\tfor `consistencyDefect` with the existing left and right tensor placements.\n    83\tThis formalization-only auxiliary for blueprint `eq:qld-nonencoding-mass`\n    84\trequires neither a probability distribution nor a normalized state, so it\n    85\tapplies in particular to the normalized state used in that calculation. -/\n    86\ttheorem avg_mass_outside_support_le_consistency_defect\n    87\t    {Question Outcome Left Right : Type*}\n    88\t    [Fintype Question] [DecidableEq Question] [Fintype Outcome] [DecidableEq Outcome]\n    89\t    [Fintype Left] [DecidableEq Left] [Fintype Right] [DecidableEq Right]\n    90\t    (mu : Distribution Question) (meas : Question → Measurement Outcome Left)\n    91\t    (reference : Question → Measurement Outcome Right)\n    92\t    (psi : EuclideanSpace ℂ (Left × Right)) (allowed : Finset Outcome)\n    93\t    (hsupport : ∀ question outcome,\n    94\t      outcome ∉ allowed → (reference question).effect outcome = 0) :\n    95\t    avgOver mu (fun question =>\n    96\t      ∑ outcome ∈ Finset.univ.filter (fun outcome => outcome ∉ allowed),\n    97\t        stateQForm psi (heteroKron ((meas question).effect outcome) 1)) ≤\n    98\t      consistencyDefect mu\n    99\t        (fun question outcome => heteroKron ((meas question).effect outcome) 1)\n   100\t        (fun question outcome => heteroKron 1 ((reference question).effect outcome)) psi := by\n   101\t  rw [SandwichProduct.consistencyDefect_placed_eq_avg_point]\n   102\t  apply avgOver_mono\n   103\t  intro question\n   104\t  exact mass_outside_support_le_point_defect\n   105\t    (meas question) (reference question) psi allowed (hsupport question)\n   106\t\n   107\tend MIPStarRE.QPBT\n     1\timport MIPStarRE.LDT.Basic.DistributionAvg\n     2\timport MIPStarRE.QPBT.Algebra.Decoding\n     3\t\n     4\t/-!\n     5\t# Real polynomial collision bounds\n     6\t\n     7\tThe existing Schwartz–Zippel estimate for bounded polynomial representatives\n     8\tis expressed as a nonnegative rational cardinality ratio. This module converts\n     9\tit to the real uniform average used by the sandwich support comparison and\n    10\tspecializes it to the polynomial outcomes of the Pauli basis test.\n    11\t\n    12\t## References\n    13\t\n    14\t* `references/qpbt-paper/04_preliminaries.tex`, `lem:schwartz-zippel`.\n    15\t* Blueprint `lem:schwartz-zippel-individual` and the collision calculation\n    16\t  preceding `eq:qld-nonencoding-mass` in `sec:separating`.\n    17\t* `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1483-1492`,\n    18\t  the consistency calculation in `lem:qld-construct-the-paulis` whose decoder\n    19\t  substitution requires the blueprint's nonencoding-mass estimate.\n    20\t* `docs/paper-gaps/qpbt_decoding-identity.tex`, for that substitution's scope.\n    21\t-/\n    22\t\n    23\tnamespace MIPStarRE.QPBT\n    24\t\n    25\topen MIPStarRE.LDT MIPStarRE.LDT.Preliminaries\n    26\t\n    27\t/-- Two distinct individual-degree-`d` polynomial representatives agree on at\n    28\tmost an `m * d / |K|` fraction of field points, expressed as a real uniform\n    29\taverage. This is the scalar collision estimate used before blueprint\n    30\t`eq:qld-nonencoding-mass`, not the nonencoding-mass estimate itself.\n    31\t\n    32\tThe field is finite and hence nonempty. No positive dimension, positive degree,\n    33\tor degree bound relative to the field size is required; representatives are\n    34\tnot identified merely because their evaluations agree. -/\n    35\ttheorem polyFunc_eval_collision_le {m d : ℕ} {K : Type*} [Field K] [Fintype K]\n    36\t    [DecidableEq K] (first second : polyFunc m K d) (hne : first ≠ second) :\n    37\t    avgOver (uniformDistribution (Fin m → K))\n    38\t      (fun point => if MvPolynomial.eval point first.1 = MvPolynomial.eval point second.1\n    39\t        then (1 : ℝ) else 0) ≤ (m * d : ℝ) / Fintype.card K := by\n    40\t  have havg :\n    41\t      avgOver (uniformDistribution (Fin m → K))\n    42\t        (fun point => if MvPolynomial.eval point first.1 = MvPolynomial.eval point second.1\n    43\t          then (1 : ℝ) else 0) =\n    44\t        (polynomialAgreementProbability m K first.1 second.1 : ℝ) := by\n    45\t    rw [avgOver_uniform_eq_inv_card_mul_sum, ← Finset.sum_filter]\n    46\t    simp [polynomialAgreementProbability, div_eq_mul_inv, mul_comm]\n    47\t  rw [havg]\n    48\t  have hbound := schwartzZippel_individualDegree first second hne\n    49\t  have hreal : (polynomialAgreementProbability m K first.1 second.1 : ℝ) ≤\n    50\t      ((((m * d : ℕ) : ℚ≥0) / Fintype.card K) : ℝ) := by\n    51\t    exact_mod_cast hbound\n    52\t  simpa using hreal\n    53\t\n    54\t/-- The collision hypothesis for the sandwich support comparison on QPBT\n    55\tpolynomial outcomes, with the field cardinality written as `P.q`.\n    56\t\n    57\tThis specializes `polyFunc_eval_collision_le` to the fixed field model and\n    58\t`evalPoly`; it adds no assumptions to the admissible parameter domain of\n    59\tblueprint `eq:qld-nonencoding-mass`. -/\n    60\ttheorem poly_eval_collision_le {P : AdmissibleParams}\n    61\t    (first second : Poly P) (hne : first ≠ second) :\n    62\t    avgOver (uniformDistribution (Fin P.m → PauliScalar P))\n    63\t      (fun point => if evalPoly first point = evalPoly second point then (1 : ℝ) else 0) ≤\n    64\t        (P.m * P.d : ℝ) / P.q := by\n    65\t  have hcard : Fintype.card (PauliScalar P) = P.q :=\n    66\t    @FieldModel.card P.q P.model.toFieldModel\n    67\t  unfold evalPoly\n    68\t  conv_rhs => rw [← hcard]\n    69\t  exact polyFunc_eval_collision_le first second hne\n    70\t\n    71\tend MIPStarRE.QPBT\n","internal_chat_message_metadata_passthrough":{"turn_id":"01a09e58-29ec-7233-b950-156ba1fc0951","create_time":1789363171.7922657}},{"type":"function_call_output","id":"fco_01a09e5b-31d2-7451-ab4c-462e2b8e0bbf","call_id":"call_t1dv7gWux0ASR9nh4H27hzts","output":"Chunk ID: 12adde\nWall time: 0.0000 seconds\nProcess exited with code 0\nOriginal token count: 4438\nOutput:\n     1\timport MIPStarRE.QPBT.Combining.ExtendedLineGame.StateTransport\n     2\t\n     3\t/-!\n     4\t# Pair-state consistency transport\n     5\t\n     6\tThis module transports consistency defects on the two-player expanded state to\n     7\tthe corresponding opposite placements on the six-register expanded state.\n     8\t\n     9\t## References\n    10\t\n    11\tThese formalization-only identities support the application of `lem:pasting`\n    12\tin `lem:qld-xz-lines`, from\n    13\t`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:950-963` and\n    14\t`references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:504-525`.\n    15\t-/\n    16\t\n    17\tnamespace MIPStarRE.QPBT\n    18\t\n    19\topen scoped MatrixOrder C