\t\n    28\tnamespace MIPStarRE.QPBT\n    29\t\n    30\topen MIPStarRE.Quantum\n    31\t\n    32\tvariable {params : AdmissibleParams} {error : ℝ}\n    33\t\n    34\t/-- The ideal Pauli basis measurement on the ancillary register, bundled using\n    35\tpositivity and completeness of the existing Pauli projectors. -/\n    36\tnoncomputable def pauliRegisterMeas (basis : PauliKind) :\n    37\t    Measurement (PauliRegister params) (PauliRegister params) :=\n    38\t  Measurement.ofSumEqOne (pauliProj basis)\n    39\t    (fun answer => Matrix.nonneg_iff_posSemidef.mpr (posSemidef_pauliProj basis answer))\n    40\t    (sum_pauliProj_eq_one basis)\n    41\t\n    42\t/-- Every bounded encoding lies in the full-field decoder's encoding image. -/\n    43\t@[simp] theorem isEncoding_encodingPoly (answer : PauliRegister params) :\n    44\t    IsEncoding (encodingPoly answer) := by\n    45\t  unfold IsEncoding\n    46\t  rw [decodeFq_lowDegreeEncoding]\n    47\t  rfl\n    48\t\n    49\tnamespace ProjectiveSetting\n    50\t\n    51\t/-- Measure the strategy Pauli answer and the ancillary ideal Pauli answer and\n    52\treturn the encoding of their sum. This complete POVM is the internal reference\n    53\tmeasurement underlying blueprint `eq:qld-nonencoding-mass`; it is not the global\n    54\tpolynomial measurement whose existence is required in `lem:qld-4-7`. -/\n    55\tnoncomputable def encodingPauliMeas (setting : ProjectiveSetting params error)\n    56\t    (side : PlayerSide) (basis : PauliKind) :\n    57\t    Measurement (Poly params) (setting.ExpandedLocalSpace side) :=\n    58\t  (tensorMeasurement (setting.pauliMeas side basis) (pauliRegisterMeas basis)).postprocess\n    59\t    fun answers => encodingPoly (answers.1 + answers.2)\n    60\t\n    61\t/-- The reference effect sums the product effects over pairs whose sum encodes\n    62\tthe specified polynomial representative. -/\n    63\ttheorem encodingPauliMeas_effect (setting : ProjectiveSetting params error)\n    64\t    (side : PlayerSide) (basis : PauliKind) (poly : Poly params) :\n    65\t    (setting.encodingPauliMeas side basis).effect poly =\n    66\t      ∑ answers ∈ Finset.univ.filter\n    67\t          (fun answers : PauliRegister params × PauliRegister params =>\n    68\t            encodingPoly (answers.1 + answers.2) = poly),\n    69\t        heteroKron ((setting.pauliMeas side basis).effect answers.1)\n    70\t          (pauliProj basis answers.2) :=\n    71\t  rfl\n    72\t\n    73\t/-- Positivity is preserved by the tensor product and the encoding postprocessing. -/\n    74\ttheorem encodingPauliMeas_effect_nonneg (setting : ProjectiveSetting params error)\n    75\t    (side : PlayerSide) (basis : PauliKind) (poly : Poly params) :\n    76\t    0 ≤ (setting.encodingPauliMeas side basis).effect poly :=\n    77\t  (setting.encodingPauliMeas side basis).pos poly\n    78\t\n    79\t/-- The reference effects sum to the identity on the strategy and ancillary registers. -/\n    80\ttheorem sum_encodingPauliMeas_effect_eq_one (setting : ProjectiveSetting params error)\n    81\t    (side : PlayerSide) (basis : PauliKind) :\n    82\t    ∑ poly, (setting.encodingPauliMeas side basis).effect poly = 1 :=\n    83\t  (setting.encodingPauliMeas side basis).sum_eq_one\n    84\t\n    85\t/-- A nonencoding polynomial has zero reference effect. This is exact support of\n    86\tthe auxiliary measurement, not a bound on the global polynomial measurement. -/\n    87\ttheorem encodingPauliMeas_effect_eq_zero_of_not_isEncoding\n    88\t    (setting : ProjectiveSetting params error) (side : PlayerSide) (basis : PauliKind)\n    89\t    (poly : Poly params) (hpoly : ¬ IsEncoding poly) :\n    90\t    (setting.encodingPauliMeas side basis).effect poly = 0 := by\n    91\t  classical\n    92\t  rw [encodingPauliMeas_effect]\n    93\t  apply Finset.sum_eq_zero\n    94\t  intro answers hanswers\n    95\t  exact False.elim (hpoly ((Finset.mem_filter.mp hanswers).2 ▸\n    96\t    isEncoding_encodingPoly (answers.1 + answers.2)))\n    97\t\n    98\t/-- Evaluating the reference polynomial is equivalent to evaluating the two Pauli\n    99\tanswers separately and adding their values. This uses linearity of the encoding,\n   100\tnot the decoder/evaluation identity for arbitrary polynomial representatives. -/\n   101\ttheorem encodingPauliMeas_postprocess_eval (setting : ProjectiveSetting params error)\n   102\t    (side : PlayerSide) (basis : PauliKind) (point : Fin params.m → PauliScalar params) :\n   103\t    (setting.encodingPauliMeas side basis).postprocess (fun poly => evalPoly poly point) =\n   104\t      (tensorMeasurement (setting.pauliEvalMeas side basis point)\n   105\t        ((pauliRegisterMeas basis).postprocess\n   106\t          (fun answer => lowDegreeEnc answer point))).postprocess\n   107\t        (fun values => values.1 + values.2) := by\n   108\t  unfold encodingPauliMeas pauliEvalMeas\n   109\t  rw [Measurement.postprocess_comp, tensorMeasurement_postprocess,\n   110\t    Measurement.postprocess_comp]\n   111\t  apply congrArg ((tensorMeasurement (setting.pauliMeas side basis)\n   112\t    (pauliRegisterMeas basis)).postprocess)\n   113\t  funext answers\n   114\t  change lowDegreeEnc (answers.1 + answers.2) point =\n   115\t    lowDegreeEnc answers.1 point + lowDegreeEnc answers.2 point\n   116\t  simp only [lowDegreeEnc_eq_dotProduct, add_dotProduct]\n   117\t\n   118\t/-- The evaluated reference effects are exactly the Pauli-answer convolution\n   119\t`K^u_a` in the proof of blueprint `eq:qld-nonencoding-mass`. This identity makes no\n   120\tapproximation or assertion of consistency with the strategy's point measurement. -/\n   121\ttheorem encodingPauliMeas_eval_effect_eq_convolution\n   122\t    (setting : ProjectiveSetting params error) (side : PlayerSide) (basis : PauliKind)\n   123\t    (point : Fin params.m → PauliScalar params) (value : PauliScalar params) :\n   124\t    ((setting.encodingPauliMeas side basis).postprocess\n   125\t      (fun poly => evalPoly poly point)).effect value =\n   126\t      ∑ values ∈ Finset.univ.filter\n   127\t          (fun values : PauliScalar params × PauliScalar params => values.1 + values.2 = value),\n   128\t        heteroKron ((setting.pauliEvalMeas side basis point).effect values.1)\n   129\t          (tauPointProj basis point values.2) := by\n   130\t  rw [encodingPauliMeas_postprocess_eval, Measurement.postprocess_effect]\n   131\t  apply Finset.sum_congr rfl\n   132\t  intro values _\n   133\t  change heteroKron ((setting.pauliEvalMeas side basis point).effect values.1)\n   134\t    (((pauliRegisterMeas basis).postprocess\n   135\t      (fun answer => lowDegreeEnc answer point)).effect values.2) = _\n   136\t  simp only [Measurement.postprocess_effect, lowDegreeEnc_eq_dotProduct]\n   137\t  rfl\n   138\t\n   139\tend ProjectiveSetting\n   140\t\n   141\tend MIPStarRE.QPBT\n   320\ttheorem completedLinePointDefect_sums_le\n   321\t    (lines : ExtendedLinesWitness setting points deltaL) :\n   322\t    (completedLinePointDefect lines .AA' .BA''\n   323\t        (directALinePointDist params.extendedDirectLd) +\n   324\t      completedLinePointDefect lines .AA' .BA''\n   325\t        (directDLinePointDist params.extendedDirectLd) ≤ 2 * deltaL) ∧\n   326\t    (completedLinePointDefect lines .BB' .AB''\n   327\t        (directALinePointDist params.extendedDirectLd) +\n   328\t      completedLinePointDefect lines .BB' .AB''\n   329\t        (directDLinePointDist params.extendedDirectLd) ≤ 2 * deltaL) := by\n   330\t  constructor\n   331\t  · have hbound : completedLinePointDefect lines .AA' .BA''\n   332\t        (directLinePointDist params.extendedDirectLd) ≤ deltaL := lines.consistent_alice\n   333\t    rw [completedLinePointDefect_eq_half_sum] at hbound\n   334\t    linarith\n   335\t  · have hbound : completedLinePointDefect lines .BB' .AB''\n   336\t        (directLinePointDist params.extendedDirectLd) ≤ deltaL := lines.consistent_bob\n   337\t    rw [completedLinePointDefect_eq_half_sum] at hbound\n   338\t    linarith\n   339\t\n   340\t/-- The bipartite state on the two expanded local spaces, with one shared EPR\n   341\tpair. It is not the six-register vector `psiHat` on a smaller index type. -/\n   342\tdef pairState (setting : ProjectiveSetting params epsilon) :\n   343\t    EuclideanSpace ℂ (setting.ExpandedLocalSpace .alice × setting.ExpandedLocalSpace .bob) :=\n   344\t  reindexState prodShuffle (vecTensor setting.toStrategy.ψ (eprState (PauliRegister params)))\n   345\t\n   346\t/-- The two-player state used by the constructed game is normalized. -/\n   347\ttheorem pairState_norm (setting : ProjectiveSetting params epsilon) :\n   348\t    ‖pairState setting‖ = 1 := by\n   349\t  change ‖reindexState prodShuffle\n   350\t    (vecTensor setting.toStrategy.ψ (eprState (PauliRegister params)))‖ = 1\n   351\t  rw [reindexState_norm_eq, vecTensor_norm_eq, setting.toStrategy.ψ_norm,\n   352\t    eprState_norm, mul_one]\n   353\t\n   354\t/-- The concrete direct-game strategy determined by the supplied measurements. -/\n   355\tdef strategy (lines : ExtendedLinesWitness setting points deltaL) :\n   356\t    Strategy (directLdGame params.extendedDirectLd) where\n   357\t  ιA := setting.ExpandedLocalSpace .alice\n   358\t  ιB := setting.ExpandedLocalSpace .bob\n   359\t  ψ := pairState setting\n   360\t  ψ_norm := pairState_norm setting\n   361\t  A := answerMeasurement lines .alice\n   362\t  B := answerMeasurement lines .bob\n   363\t\n   364\t/-- A wrong-format answer pair has zero Born weight in the constructed strategy. -/\n   365\ttheorem outcomeWeight_eq_zero_of_invalid\n   366\t    (lines : ExtendedLinesWitness setting points deltaL)\n   367\t    (questionA questionB : DirectLdQuestion params.extendedDirectLd)\n   368\t    (answerA answerB : DirectLdAnswer params.extendedDirectLd)\n   369\t    (hinvalid : validDirectLdAnswer questionA.1 answerA = false ∨\n   370\t      validDirectLdAnswer questionB.1 answerB = false) :\n   120\t    (u : EuclideanSpace ℂ ι) :\n   121\t    DistanceCalculus.stateQForm u (1 : Op ι) = ‖u‖ ^ 2 := by\n   122\t  unfold DistanceCalculus.stateQForm\n   123\t  rw [WinImplications.applyOperatorToState_one]\n   124\t  simpa using (inner_self_eq_norm_sq (𝕜 := ℂ) u)\n   125\t\n   126\tnamespace ProjectiveSetting\n   127\t\n   128\t/-- Acting with the same Pauli point projector on both halves of the EPR state\n   129\tequals acting on one half. Symmetry transports the right action to the left,\n   130\twhere idempotence absorbs the repeated projector. This is the perfect\n   131\tancillary consistency used in item 1 of `lem:qld-comm-cons`, paper\n   132\t`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:455-465`. -/\n   133\ttheorem tauPointProj_pair_mulVec_eprState {P : AdmissibleParams}\n   134\t    (W : PauliKind) (u : Fin P.m → PauliScalar P) (a : PauliScalar P) :\n   135\t    (heteroKron (tauPointProj W u a) (tauPointProj W u a)).mulVec\n   136\t        (eprState (PauliRegister P)) =\n   137\t      (heteroKron (tauPointProj W u a) 1).mulVec\n   138\t        (eprState (PauliRegister P)) := by\n   139\t  let T := tauPointProj W u a\n   140\t  have hfactor : heteroKron T T = heteroKron T 1 * heteroKron 1 T := by\n   141\t    rw [heteroKron_mul, Matrix.mul_one, Matrix.one_mul]\n   142\t  rw [hfactor, ← Matrix.mulVec_mulVec,\n   143\t    ← epr_action_eq_of_transpose T (tauPointProj_transpose W u a),\n   144\t    Matrix.mulVec_mulVec, heteroKron_mul, Matrix.mul_one,\n   145\t    tauPointProj_mul_tauPointProj, if_pos rfl]\n   146\t\n   147\t/-- The diagonal overlap of the two Pauli point measurements on an EPR pair is\n   148\tone. Thus the ancillary measurement contributes no consistency defect. This is\n   149\tthe perfect ancillary consistency in item 1 of `lem:qld-comm-cons`, paper\n   150\t`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:455-465`. -/\n   151\ttheorem sum_tauPointProj_pair_stateQForm_eprState {P : AdmissibleParams}\n   152\t    (W : PauliKind) (u : Fin P.m → PauliScalar P) :\n   153\t    ∑ a : PauliScalar P,\n   154\t        DistanceCalculus.stateQForm (eprState (PauliRegister P))\n   155\t          (heteroKron (tauPointProj W u a) (tauPointProj W u a)) = 1 := by\n   156\t  have hterm (a : PauliScalar P) :\n   157\t      DistanceCalculus.stateQForm (eprState (PauliRegister P))\n   158\t          (heteroKron (tauPointProj W u a) (tauPointProj W u a)) =\n   159\t        DistanceCalculus.stateQForm (eprState (PauliRegister P))\n   160\t          (heteroKron (tauPointProj W u a) (1 : Op (PauliRegister P))) := by\n   161\t    unfold DistanceCalculus.stateQForm\n   162\t    congr 2\n   163\t    ext p\n   164\t    simpa [applyOperatorToState] using\n   165\t      congrFun (tauPointProj_pair_mulVec_eprState W u a) p\n   166\t  simp_rw [hterm]\n   167\t  have hsumop :\n   168\t      (∑ a : PauliScalar P,\n   169\t          heteroKron (tauPointProj W u a) (1 : Op (PauliRegister P))) =\n   170\t        heteroKron (∑ a : PauliScalar P, tauPointProj W u a)\n   171\t          (1 : Op (PauliRegister P)) := by\n   172\t    ext i j\n   173\t    rcases i with ⟨i₁, i₂⟩\n   174\t    rcases j with ⟨j₁, j₂⟩\n   175\t    unfold heteroKron Matrix.kronecker Matrix.kroneckerMap\n   475\t\n   476\t/-- Expanded point effects are positive semidefinite. This is the positivity\n   477\tobligation in `def:expanded-point-measurement`, paper\n   478\t`14_analysis_of_the_pauli_basis_test.tex:384-418`. -/\n   479\ttheorem expPointOp_nonneg (S : ProjectiveSetting P ε) (side : PlayerSide)\n   480\t    (W : PauliKind) (u : Fin P.m → PauliScalar P) (a : PauliScalar P) :\n   481\t    0 ≤ S.expPointOp side W u a := by\n   482\t  rw [expPointOp_eq_convolution]\n   483\t  exact Finset.sum_nonneg fun p hp => Quantum.kronecker_nonneg\n   484\t    ((S.pointMeas side W u).pos p.1) (tauPointProj_nonneg W u p.2)\n   485\t\n   486\t/-- Expanded point effects sum to the identity. This is the completeness\n   487\tobligation in `def:expanded-point-measurement`, paper\n   488\t`14_analysis_of_the_pauli_basis_test.tex:384-418`. -/\n   489\ttheorem expPointOp_sum_eq_one (S : ProjectiveSetting P ε) (side : PlayerSide)\n   490\t    (W : PauliKind) (u : Fin P.m → PauliScalar P) :\n   491\t    ∑ a, S.expPointOp side W u a = 1 := by\n   492\t  simp_rw [expPointOp_eq_convolution]\n   493\t  calc\n   494\t    (∑ a, ∑ p ∈ Finset.univ.filter\n   495\t        (fun p : PauliScalar P × PauliScalar P => p.1 + p.2 = a),\n   496\t      heteroKron ((S.pointMeas side W u).effect p.1)\n   497\t        (tauPointProj W u p.2)) =\n   498\t      ∑ p : PauliScalar P × PauliScalar P,\n   499\t        heteroKron ((S.pointMeas side W u).effect p.1)\n   500\t          (tauPointProj W u p.2) := by\n   501\t      let f : PauliScalar P × PauliScalar P → PauliScalar P :=\n   502\t        fun p => p.1 + p.2\n   503\t      let A : PauliScalar P × PauliScalar P →\n   504\t          Op (S.ExpandedLocalSpace side) := fun p =>\n   505\t        heteroKron ((S.pointMeas side W u).effect p.1)\n   506\t          (tauPointProj W u p.2)\n   507\t      change (∑ a, ∑ p ∈ Finset.univ.filter (fun p => f p = a), A p) =\n   508\t        ∑ p, A p\n   509\t      exact Finset.sum_fiberwise Finset.univ f A\n   510\t    _ = heteroKron (∑ x, (S.pointMeas side W u).effect x)\n   511\t        (∑ y, tauPointProj W u y) := by\n   512\t      rw [Fintype.sum_prod_type]\n   513\t      exact (heteroKron_sum_sum _ _).symm\n   514\t    _ = 1 := by\n   515\t      rw [(S.pointMeas side W u).sum_eq_one,\n   516\t        sum_tauPointProj_eq_one (P := P)]\n   517\t      exact Matrix.one_kronecker_one\n   518\t\n   519\t/-- The complete expanded point measurement on the chosen player and Pauli\n   520\tregister. Its effects are those of `def:expanded-point-measurement`, paper\n   521\t`14_analysis_of_the_pauli_basis_test.tex:384-418`, blueprint\n   522\t`def:expanded-point-measurement`. -/\n   523\tnoncomputable def pointMeasExp (S : ProjectiveSetting P ε) (side : PlayerSide)\n   524\t    (W : PauliKind) (u : Fin P.m → PauliScalar P) :\n   525\t    Measurement (PauliScalar P) (S.ExpandedLocalSpace side) :=\n   526\t  Measurement.ofSumEqOne (S.expPointOp side W u)\n   527\t    (S.expPointOp_nonneg side W u) (S.expPointOp_sum_eq_one side W u)\n   528\t\n   529\t/-- The expanded point measurement is the addition postprocessing of its fine\n   530\tstrategy--Pauli product measurement. This is the data-processing presentation\n   531\tused in item 1 of `lem:qld-comm-cons`, paper\n   532\t`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:390-411`,\n   533\tblueprint `lem:expanded-point-measurement-properties`. -/\n   534\ttheorem pointMeasExp_effect_eq_pointTauMeas_postprocess\n   535\t    (S : ProjectiveSetting P ε) (side : PlayerSide) (W : PauliKind)\n   536\t    (u : Fin P.m → PauliScalar P) (a : PauliScalar P) :\n   537\t    (S.pointMeasExp side W u).effect a =\n   538\t      ((S.pointTauMeas side W u).postprocess (fun p => p.1 + p.2)).effect a := by\n   539\t  change S.expPointOp side W u a = _\n   540\t  rw [MIPStarRE.Quantum.Measurement.postprocess_effect]\n   541\t  exact expPointOp_eq_convolution S side W u a\n   542\t\n   543\t/-- Expanded observables inherit the additive representation law. -/\n   544\tprivate theorem expObs_mul (S : ProjectiveSetting P ε) (side : PlayerSide)\n   545\t    (W : PauliKind) (r s : PauliScalar P)\n","internal_chat_message_metadata_passthrough":{"turn_id":"01a09e58-29ec-7233-b950-156ba1fc0951","create_time":1789363200.611523}},{"type":"function_call_output","id":"fco_01a09e5b-a265-7b31-a43c-dc02c59f8199","call_id":"call_zqRPson8jw1ZOh2KXkW3nFIa","output":"Chunk ID: b542fc\nWall time: 0.0000 seconds\nProcess exited with code 0\nOriginal token count: 4512\nOutput:\n    35\t\n    36\t/-- Select the polynomial belonging to a Pauli basis from a joint polynomial\n    37\toutcome. This is the marginalization used at paper\n    38\t`14_analysis_of_the_pauli_basis_test.tex:1421-1423` and blueprint\n    39\t`def:s-w-marginals`. -/\n    40\tdef selectPoly {P : AdmissibleParams} (W : PauliKind) : PolyPair P -> Poly P\n    41\t  | pair => match W with\n    42\t    | .X => pair.1\n    43\t    | .Z => pair.2\n    44\t\n    45\tend PauliKind\n    46\t\n    47\tnamespace GlobalPairWitness\n    48\t\n    49\t/-- The single-basis marginal of the global polynomial-pair measurement.\n    50\tThis is blueprint\n    51\t`def:s-w-marginals`, paper\n    52\t`14_analysis_of_the_pauli_basis_test.tex:1421-1423`. -/\n    53\tnoncomputable def marginalPoly {P : AdmissibleParams} {epsilon delta : ℝ}\n    54\t    {S : ProjectiveSetting P epsilon} (w : GlobalPairWitness S delta)\n    55\t    (side : PlayerSide) (W : PauliKind) :\n    56\t    Measurement (Poly P) (S.ExpandedLocalSpace side) :=\n    57\t  (w.Smeas side).postprocess W.selectPoly\n    58\t\n    59\t/-- The single-basis marginal remains a projective measurement. This is the\n    60\tprojectivity assertion implicit in blueprint\n    61\t`def:s-w-marginals`, paper\n    62\t`14_analysis_of_the_pauli_basis_test.tex:1421-1423`. Finite postprocessing\n    63\tpreserves projectivity, independently of the construction of the joint\n    64\tmeasurement. -/\n    65\ttheorem marginalPoly_isProjective {P : AdmissibleParams} {epsilon delta : ℝ}\n    66\t    {S : ProjectiveSetting P epsilon} (w : GlobalPairWitness S delta)\n    67\t    (side : PlayerSide) (W : PauliKind) :\n    68\t    Measurement.IsProjective (w.marginalPoly side W) := by\n    69\t  exact SandwichProduct.postprocess_isProjective\n    70\t    (w.Smeas side) (w.projective side) W.selectPoly\n    71\t\n    72\tend GlobalPairWitness\n    73\t\n    74\t/-- The pulled-apart projective-measurement effect from Equation `eq:tilde_M`.\n    75\tThe polynomial marginal acts on the player's expanded local space and the\n    76\tdot-product projector acts on the newly adjoined register. Blueprint\n    77\t`eq:tilde_M`; paper\n    78\t`14_analysis_of_the_pauli_basis_test.tex:1425-1435`. -/\n    79\tnoncomputable def tildeM {P : AdmissibleParams} {epsilon delta : ℝ}\n    80\t    {S : ProjectiveSetting P epsilon} (w : GlobalPairWitness S delta)\n    81\t    (side : PlayerSide) (W : PauliKind) (u : PauliRegister P)\n    82\t    (a : PauliScalar P) : Op (ExtractionBlock P (S.LocalSpace side)) :=\n    83\t  ∑ g : Poly P,\n    84\t    heteroKron ((w.marginalPoly side W).effect g)\n    85\t      (tauDotProj W u (dotProduct (decodeFq g) u - a))\n    86\t\n    87\t/-- Each pulled-apart effect is a projector, as asserted in\n    88\tblueprint `lem:tilde-m-projective`, paper\n    89\t`14_analysis_of_the_pauli_basis_test.tex:1425-1435`.\n    90\t\n    91\tEach tensor summand is projective. Distinct polynomial marginals are\n    92\torthogonal, so their tensor summands are orthogonal as well. -/\n    93\ttheorem tildeM_isProj {P : AdmissibleParams} {epsilon delta : ℝ}\n    94\t    {S : ProjectiveSetting P epsilon} (w : GlobalPairWitness S delta)\n    95\t    (side : PlayerSide) (W : PauliKind) (u : PauliRegister P)\n    96\t    (a : PauliScalar P) :\n    97\t    IsProj (tildeM w side W u a) := by\n    98\t  classical\n    99\t  have hproj (g : Poly P) : IsProj\n   100\t      (heteroKron ((w.marginalPoly side W).effect g)\n   101\t        (tauDotProj W u (dotProduct (decodeFq g) u - a))) :=\n   102\t    MakingMeasurementsProjective.isProj_kronecker\n   103\t      (w.marginalPoly_isProjective side W g) (tauDotProj_isProj W u _)\n   104\t  unfold tildeM\n   105\t  constructor\n   106\t  · change (∑ g : Poly P, _) * (∑ g : Poly P, _) = _\n   107\t    rw [Finset.sum_mul]\n   108\t    refine Finset.sum_congr rfl fun g _ => ?_\n   109\t    rw [Matrix.mul_sum, Finset.sum_eq_single g]\n   110\t    · exact (hproj g).isIdempotentElem\n   111\t    · intro g' _ hg'\n   112\t      rw [heteroKron_mul, MagicSquareRigidity.mul_eq_zero_of_isProj_family\n   113\t        (w.marginalPoly_isProjective side W) (w.marginalPoly side W).sum_le_one\n   114\t        hg'.symm]\n   115\t      simp [heteroKron]\n   116\t    · intro hg\n   117\t      exact (hg (Finset.mem_univ g)).elim\n   118\t  · change (∑ g : Poly P, _)ᴴ = _\n   119\t    rw [Matrix.conjTranspose_sum]\n   120\t    exact Finset.sum_congr rfl fun g _ => (hproj g).isSelfAdjoint\n   121\t\n   122\t/-- The pulled-apart effects are complete for each fixed basis and Pauli\n   123\tregister vector. This is the completeness assertion in\n   124\tblueprint `lem:tilde-m-projective`, paper\n   125\t`14_analysis_of_the_pauli_basis_test.tex:1425-1435`.\n   126\t\n   127\tFor each polynomial, subtracting the scalar outcome from its decoded dot\n   128\tproduct permutes the field. Completeness then follows by summing the\n   129\tdot-product projectors and the polynomial marginal effects. -/\n   130\ttheorem sum_tildeM_eq_one {P : AdmissibleParams} {epsilon delta : ℝ}\n   131\t    {S : ProjectiveSetting P epsilon} (w : GlobalPairWitness S delta)\n   132\t    (side : PlayerSide) (W : PauliKind) (u : PauliRegister P) :\n   133\t    ∑ a : PauliScalar P, tildeM w side W u a = 1 := by\n   134\t  classical\n   135\t  simp only [tildeM]\n   136\t  rw [Finset.sum_comm]\n   137\t  calc\n   138\t    _ = ∑ g : Poly P, heteroKron ((w.marginalPoly side W).effect g)\n   139\t        (∑ a : PauliScalar P, tauDotProj W u (dotProduct (decodeFq g) u - a)) := by\n   140\t      exact Finset.sum_congr rfl fun g _ =>\n   141\t        (DistanceCalculus.heteroKron_finset_sum_right _ _ _).symm\n   142\t    _ = ∑ g : Poly P, heteroKron ((w.marginalPoly side W).effect g) 1 := by\n   143\t      refine Finset.sum_congr rfl fun g _ => ?_\n   144\t      congr 1\n   145\t      calc\n   146\t        _ = ∑ a : PauliScalar P, tauDotProj W u a :=\n   147\t          (Equiv.subLeft (dotProduct (decodeFq g) u)).sum_comp (tauDotProj W u)\n   148\t        _ = 1 := sum_tauDotProj_eq_one W u\n   149\t    _ = heteroKron (∑ g : Poly P, (w.marginalPoly side W).effect g) 1 :=\n   150\t      (DistanceCalculus.heteroKron_finset_sum_left _ _ _).symm\n   151\t    _ = 1 := by rw [(w.marginalPoly side W).sum_eq_one, heteroKron_one_one]\n   152\t\n   153\t/-- The binary observable obtained from the trace coarse-graining of `tildeM`.\n   154\tThis is Equation `eq:def-tildewj` in blueprint\n   155\t`def:tilde-w-observables`, paper\n   156\t`14_analysis_of_the_pauli_basis_test.tex:1437-1442`. -/\n   157\tnoncomputable def tildeObs {P : AdmissibleParams} {epsilon delta : ℝ}\n   158\t    {S : ProjectiveSetting P epsilon} (w : GlobalPairWitness S delta)\n   159\t    (side : PlayerSide) (W : PauliKind) (u : PauliRegister P)\n   160\t    (j : Fin P.model.basisDim) : Op (ExtractionBlock P (S.LocalSpace side)) :=\n   161\t  ∑ a : PauliScalar P,\n   162\t    phaseSign (fixedBinTrace P.model (P.model.basis j * a)) •\n   163\t      tildeM w side W u a\n   164\t\n   165\t/-- Fourier regrouping of the dot-product effects after translating their\n   166\toutcomes. This is the change of variables in the product calculation at paper\n   167\t`14_analysis_of_the_pauli_basis_test.tex:1442-1450`, supporting blueprint\n   168\t`lem:tildew-product-form`. It uses only the definition of the coarse-graining,\n   169\tnot its projectivity. -/\n   170\tprivate theorem sum_phaseSign_tauDotProj_sub {params : AdmissibleParams}\n   171\t    (kind : PauliKind) (vector : PauliRegister params)\n   172\t    (coefficient offset : PauliScalar params) :\n   173\t    (∑ value : PauliScalar params,\n   174\t      phaseSign (fixedBinTrace params.model (coefficient * value)) •\n   175\t        tauDotProj kind vector (offset - value)) =\n   176\t      phaseSign (fixedBinTrace params.model (coefficient * offset)) •\n   177\t        tauObservable kind (coefficient • vector) := by\n   178\t  classical\n   179\t  calc\n   180\t    _ = ∑ value : PauliScalar params,\n   200\t      rw [tauObservable_eq_sum_pauliProj, Finset.smul_sum]\n   201\t      apply Finset.sum_congr rfl\n   202\t      intro label _\n   203\t      rw [smul_smul, smul_dotProduct, smul_eq_mul, dotProduct_comm vector label]\n   204\t      congr 1\n   205\t      rw [mul_sub, fixedBinTrace, map_sub, sub_eq_add_neg,\n   206\t        ZMod.neg_eq_self_mod_two, phaseSign_add]\n   207\t\n   208\t/-- Product form of the pulled-apart observable, Equation\n   209\t`eq:tildewj-product-form` of `lem:tildew-product-form`. Blueprint\n   210\t`lem:tildew-product-form`; paper\n   211\t`14_analysis_of_the_pauli_basis_test.tex:1442-1450`. The finite Fourier\n   212\tregrouping uses `tauObservable_eq_sum_pauliProj` and the definitions of both\n   213\tmarginalizations, independently of dot-product projectivity or consistency\n   214\testimates. -/\n   215\ttheorem tildeObs_eq_heteroKron {P : AdmissibleParams} {epsilon delta : ℝ}\n   216\t    {S : ProjectiveSetting P epsilon} (w : GlobalPairWitness S delta)\n   217\t    (side : PlayerSide) (W : PauliKind) (u : PauliRegister P)\n   218\t    (j : Fin P.model.basisDim) :\n   219\t    tildeObs w side W u j =\n   220\t      heteroKron\n   221\t        (∑ pair : PolyPair P,\n   222\t          phaseSign (fixedBinTrace P.model\n   223\t            (P.model.basis j * dotProduct (decodeFq (W.selectPoly pair)) u)) •\n   224\t            (w.Smeas side).effect pair)\n   225\t        (tauObservable W (P.model.basis j • u)) := by\n   226\t  classical\n   227\t  simp only [tildeObs, tildeM, Finset.smul_sum]\n   228\t  rw [Finset.sum_comm]\n   229\t  calc\n   230\t    _ = ∑ polynomial : Poly P,\n   231\t        heteroKron ((w.marginalPoly side W).effect polynomial)\n   232\t          (∑ value : PauliScalar P,\n   233\t            phaseSign (fixedBinTrace P.model (P.model.basis j * value)) •\n   234\t              tauDotProj W u (dotProduct (decodeFq polynomial) u - value)) := by\n   235\t      apply Finset.sum_congr rfl\n   236\t      intro polynomial _\n   237\t      rw [DistanceCalculus.heteroKron_finset_sum_right]\n   238\t      apply Finset.sum_congr rfl\n   239\t      intro value _\n   240\t      exact (Matrix.kronecker_smul _ _ _).symm\n   241\t    _ = heteroKron\n   242\t        (∑ polynomial : Poly P,\n   243\t          phaseSign (fixedBinTrace P.model\n   244\t            (P.model.basis j * dotProduct (decodeFq polynomial) u)) •\n   245\t              (w.marginalPoly side W).effect polynomial)\n   246\t        (tauObservable W (P.model.basis j • u)) := by\n   247\t      simp_rw [sum_phaseSign_tauDotProj_sub]\n   248\t      rw [DistanceCalculus.heteroKron_finset_sum_left]\n   249\t      apply Finset.sum_congr rfl\n   250\t      intro polynomial _\n   251\t      simp only [heteroKron, Matrix.kronecker, Matrix.kronecker_smul,\n   252\t        Matrix.smul_kronecker]\n   253\t    _ = _ := by\n   254\t      congr 1\n   255\t      simp only [GlobalPairWitness.marginalPoly, Measurement.postprocess_effect,\n   256\t        Finset.smul_sum]\n   257\t      rw [← Finset.sum_fiberwise Finset.univ W.selectPoly\n   258\t        (fun pair => phaseSign (fixedBinTrace P.model\n   259\t          (P.model.basis j * dotProduct (decodeFq (W.selectPoly pair)) u)) •\n   260\t            (w.Smeas side).effect pair)]\n   261\t      apply Finset.sum_congr rfl\n   262\t      intro polynomial _\n   263\t      apply Finset.sum_congr rfl\n   264\t      intro pair hpair\n   265\t      rw [(Finset.mem_filter.mp hpair).2]\n   266\t\n   267\t/-- The complex binary character agrees with the real sign used in spectral sums.\n   268\tThis formalization-only identity permits its use\n   269\tin the involution and commutation assertions of `lem:tildew-product-form`. -/\n   270\tprivate theorem phaseSign_eq_complex_bitSign (value : ZMod 2) :\n   271\t    phaseSign value = (MagicSquareRigidity.bitSign value : ℂ) := by\n   272\t  rcases zmod_two_eq_zero_or_one value with hvalue | hvalue <;>\n   273\t    subst value <;> norm_num [phaseSign, MagicSquareRigidity.bitSign, ZMod.val_one]\n   274\t\n   275\t/-- Every pulled-apart observable is Hermitian, as asserted in\n   276\tblueprint `lem:tildew-product-f